// Live fleet numbers come from the file the sovereign bot writes. The read happens
// on the server and only pre-formatted strings reach the client component, so server
// HTML and client HTML cannot disagree (no hydration mismatch).
function readState(): { revenueToday: number; lastRunLabel: string | null } {
  try {
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const fs = require("node:fs") as typeof import("node:fs");
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const path = require("node:path") as typeof import("node:path");
    const file = path.join(process.cwd(), "dropper.sovereign-state.json");
    const state = JSON.parse(fs.readFileSync(file, "utf8")) as { lastExecutedUtc?: string; revenueTodayUsd?: number };
    const label = state.lastExecutedUtc
      ? new Intl.DateTimeFormat("en-US", {
          timeZone: "America/Denver",
          dateStyle: "medium",
          timeStyle: "short"
        }).format(new Date(state.lastExecutedUtc)) + " MT"
      : null;
    return { revenueToday: state.revenueTodayUsd ?? 0, lastRunLabel: label };
  } catch {
    return { revenueToday: 0, lastRunLabel: null };
  }
}

export default function Page() {
  const { revenueToday, lastRunLabel } = readState();
  return <DropperOSPage revenueToday={revenueToday} lastRunLabel={lastRunLabel} />;
}

